=== lib/wallet.ts ===
import { LedgerEntryType } from "@/lib/generated/prisma/enums";
import type { PayoutStatus } from "@/lib/generated/prisma/enums";
import type { Prisma, PrismaClient } from "@/lib/generated/prisma/client";

// Feature 6 re-reads the available balance inside a serializable transaction
// before committing a payout, so every derivation takes its client rather than
// closing over the singleton. Passing `tx` is the whole point.
type WalletClient = PrismaClient | Prisma.TransactionClient;

export async function sumPendingEarnings(
  client: WalletClient,
  creatorId: string,
): Promise<number> {
  const { _sum } = await client.ledgerEntry.aggregate({
    where: { creatorId, type: LedgerEntryType.EARNING_PENDING },
    _sum: { amountMinor: true },
  });

  return _sum.amountMinor ?? 0;
}

// Everything that is not a pending earning, which is why a hold needs no
// special case: it is already a negative row.
export async function sumAvailableBalance(
  client: WalletClient,
  creatorId: string,
): Promise<number> {
  const { _sum } = await client.ledgerEntry.aggregate({
    where: { creatorId, type: { not: LedgerEntryType.EARNING_PENDING } },
    _sum: { amountMinor: true },
  });

  return _sum.amountMinor ?? 0;
}

export type WalletHistoryRow =
  | {
      kind: "entry";
      id: string;
      date: Date;
      description: string;
      amountMinor: number;
    }
  | {
      kind: "payout";
      id: string;
      date: Date;
      amountMinor: number;
      status: PayoutStatus;
      decidedAt: Date | null;
    };

// A payout request writes one to three ledger rows, so showing raw ledger rows
// would make a single withdrawal look like three events. The request collapses
// into one row and only entries with no request behind them stand alone. This
// is presentation only: the balances above still come from the full ledger.
export async function getWalletHistory(
  client: WalletClient,
  creatorId: string,
): Promise<WalletHistoryRow[]> {
  const [entries, payouts] = await Promise.all([
    client.ledgerEntry.findMany({
      where: { creatorId, payoutRequestId: null },
      orderBy: { createdAt: "desc" },
    }),
    client.payoutRequest.findMany({
      where: { creatorId },
      orderBy: { createdAt: "desc" },
    }),
  ]);

  const rows: WalletHistoryRow[] = [
    ...entries.map((entry) => ({
      kind: "entry" as const,
      id: entry.id,
      date: entry.createdAt,
      description: entry.description,
      amountMinor: entry.amountMinor,
    })),
    ...payouts.map((payout) => ({
      kind: "payout" as const,
      id: payout.id,
      // The request date, because that is when the hold moved the balance.
      date: payout.createdAt,
      // Stored positive; shown as money leaving, matching the ledger's sign.
      amountMinor: -payout.amountMinor,
      status: payout.status,
      decidedAt: payout.decidedAt,
    })),
  ];

  return rows.sort((a, b) => b.date.getTime() - a.date.getTime());
}

=== lib/creator.ts ===
import { cache } from "react";
import type { Creator } from "@/lib/generated/prisma/client";
import { prisma } from "@/lib/prisma";

// The portal has exactly one creator and no auth, so every surface resolves it
// here on the server. Nothing takes a creator id from the client.
export const getCreator = cache(async (): Promise<Creator> => {
  const creator = await prisma.creator.findFirst({
    orderBy: { createdAt: "asc" },
  });

  if (!creator) {
    throw new Error(
      "No creator found. Run `npm run db:seed` to populate the portal.",
    );
  }

  return creator;
});

=== lib/format.ts ===
// Locale and time zone are pinned rather than left to the environment: these
// strings are produced on the server and shipped as HTML, so a client in
// another zone must not disagree with what was rendered.
const countFormatter = new Intl.NumberFormat("en-US");

const timestampFormatter = new Intl.DateTimeFormat("en-US", {
  dateStyle: "medium",
  timeStyle: "short",
  timeZone: "UTC",
});

const dateFormatter = new Intl.DateTimeFormat("en-US", {
  dateStyle: "medium",
  timeZone: "UTC",
});

export function formatCount(value: number): string {
  return countFormatter.format(value);
}

// Money never leaves integer arithmetic. Handing Intl a `minor / 100` float
// would derive the cents from a binary fraction; here the cents come from an
// exact modulo, and the dollars from dividing a value already known to be a
// multiple of 100, so neither can round.
export function formatMinor(amountMinor: number): string {
  const negative = amountMinor < 0;
  const absolute = Math.abs(amountMinor);
  const cents = absolute % 100;
  const dollars = (absolute - cents) / 100;

  return `${negative ? "-" : ""}$${countFormatter.format(dollars)}.${String(cents).padStart(2, "0")}`;
}

export function formatTimestamp(value: Date): string {
  return `${timestampFormatter.format(value)} UTC`;
}

export function formatDate(value: Date): string {
  return dateFormatter.format(value);
}

=== lib/prisma.ts ===
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@/lib/generated/prisma/client";

function connectionString(): string {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error("DATABASE_URL is not set. Copy .env.example to .env.local.");
  }
  return url;
}

// Pooled connection: Prisma 7 talks to Postgres through a driver adapter, so
// the app gets Neon's pooler while the CLI keeps the direct URL for migrations.
function createPrismaClient() {
  return new PrismaClient({
    adapter: new PrismaPg({ connectionString: connectionString() }),
  });
}

const globalForPrisma = globalThis as unknown as {
  prisma?: ReturnType<typeof createPrismaClient>;
};

export const prisma = globalForPrisma.prisma ?? createPrismaClient();

// Without this, every dev hot reload would open another connection pool.
if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}

