import { LedgerEntryType } from "@/lib/generated/prisma/enums";
import { createPayoutRequest } from "@/lib/payout";
import { prisma } from "@/lib/prisma";
import { sumAvailableBalance } from "@/lib/wallet";

async function counts(creatorId: string) {
  const [requests, holds, available] = await Promise.all([
    prisma.payoutRequest.count({ where: { creatorId } }),
    prisma.ledgerEntry.count({
      where: { creatorId, type: LedgerEntryType.PAYOUT_HOLD },
    }),
    sumAvailableBalance(prisma, creatorId),
  ]);
  return { requests, holds, available };
}

function check(label: string, actual: unknown, expected: unknown) {
  const pass = JSON.stringify(actual) === JSON.stringify(expected);
  console.log(
    `${pass ? "PASS" : "FAIL"}  ${label}\n      expected ${JSON.stringify(expected)}\n      actual   ${JSON.stringify(actual)}`,
  );
  if (!pass) process.exitCode = 1;
}

async function main() {
  const creator = await prisma.creator.findFirstOrThrow();
  const id = creator.id;

  const start = await counts(id);
  console.log("\nseeded baseline:", start, "\n");
  check("baseline available balance is the seeded 128450", start.available, 128450);

  console.log("--- 1. a valid request writes one request and one hold ---");
  const ok = await createPayoutRequest(prisma, {
    creatorId: id,
    amountMinor: 20000,
    idempotencyKey: "evidence-valid",
  });
  const afterValid = await counts(id);
  check("result kind", ok.kind, "created");
  check("requests +1", afterValid.requests - start.requests, 1);
  check("holds +1", afterValid.holds - start.holds, 1);
  check("available dropped by exactly 20000", start.available - afterValid.available, 20000);

  console.log("\n--- 2. an overdraft writes nothing ---");
  const over = await createPayoutRequest(prisma, {
    creatorId: id,
    amountMinor: afterValid.available + 1,
    idempotencyKey: "evidence-overdraft",
  });
  const afterOver = await counts(id);
  check("result kind", over.kind, "overdrawn");
  check("requests unchanged", afterOver.requests, afterValid.requests);
  check("holds unchanged", afterOver.holds, afterValid.holds);
  check("available unchanged", afterOver.available, afterValid.available);

  console.log("\n--- 3. one idempotency key yields one request ---");
  const first = await createPayoutRequest(prisma, {
    creatorId: id,
    amountMinor: 1500,
    idempotencyKey: "evidence-idempotent",
  });
  const second = await createPayoutRequest(prisma, {
    creatorId: id,
    amountMinor: 1500,
    idempotencyKey: "evidence-idempotent",
  });
  const afterIdem = await counts(id);
  check("first kind", first.kind, "created");
  check("second kind", second.kind, "duplicate");
  check(
    "both point at the same row",
    first.kind !== "overdrawn" && second.kind !== "overdrawn" && first.request.id === second.request.id,
    true,
  );
  check("requests +1 across two calls", afterIdem.requests - afterOver.requests, 1);
  check("holds +1 across two calls", afterIdem.holds - afterOver.holds, 1);
  check("available dropped by 1500 once", afterOver.available - afterIdem.available, 1500);

  console.log("\n--- 4. re-seeding, then two racing requests ---");
  await prisma.$disconnect();
}

main().catch(async (error) => {
  console.error("script failed:", error);
  process.exitCode = 1;
  await prisma.$disconnect();
});

