import { LedgerEntryType } from "@/lib/generated/prisma/enums";
import { createPayoutRequest, type CreatePayoutResult } from "@/lib/payout";
import { prisma } from "@/lib/prisma";
import { sumAvailableBalance } from "@/lib/wallet";

function check(label: string, actual: unknown, expected: unknown) {
  const pass = JSON.stringify(actual) === JSON.stringify(expected);
  console.log(`${pass ? "PASS" : "FAIL"}  ${label}  (expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)})`);
  if (!pass) process.exitCode = 1;
}

async function race(creatorId: string, label: string, amounts: number[]) {
  console.log(`\n--- ${label} ---`);
  const before = await sumAvailableBalance(prisma, creatorId);

  // Fired together, not awaited in turn. Each opens its own serializable
  // transaction, so Postgres has to arbitrate rather than the application.
  const settled = await Promise.all(
    amounts.map((amountMinor, index) =>
      createPayoutRequest(prisma, {
        creatorId,
        amountMinor,
        idempotencyKey: `${label}-${index}-${Date.now()}`,
      }).then(
        (result): { ok: true; result: CreatePayoutResult } => ({ ok: true, result }),
        (error: unknown): { ok: false; error: string } => ({
          ok: false,
          error: (error as { code?: string })?.code ?? String(error),
        }),
      ),
    ),
  );

  const created = settled.filter((s) => s.ok && s.result.kind === "created").length;
  const overdrawn = settled.filter((s) => s.ok && s.result.kind === "overdrawn").length;
  const threw = settled.filter((s) => !s.ok);

  const after = await sumAvailableBalance(prisma, creatorId);
  const requests = await prisma.payoutRequest.count({ where: { creatorId } });
  const holds = await prisma.ledgerEntry.count({
    where: { creatorId, type: LedgerEntryType.PAYOUT_HOLD },
  });

  console.log(`  balance ${before} -> ${after}`);
  console.log(`  created=${created} overdrawn=${overdrawn} threw=${threw.length}`, threw.map((t) => !t.ok && t.error));

  return { before, after, created, overdrawn, threw: threw.length, requests, holds };
}

async function main() {
  const creator = await prisma.creator.findFirstOrThrow();
  const id = creator.id;

  const baseline = await sumAvailableBalance(prisma, id);
  console.log("seeded baseline available:", baseline);
  if (baseline !== 128450) {
    console.error("FAIL  expected a freshly seeded 128450 balance. Run `npm run db:seed` first.");
    process.exitCode = 1;
    await prisma.$disconnect();
    return;
  }

  // Two requests of 70000 against 128450: either alone fits, together they do
  // not. Exactly one must win.
  const two = await race(id, "two 70000 requests against 128450", [70000, 70000]);
  check("exactly one committed", two.created, 1);
  check("the loser was rejected as an overdraft, not an error", two.overdrawn, 1);
  check("nothing threw", two.threw, 0);
  check("available is 128450 - 70000", two.after, 58450);
  check("one new request beyond the seeded one", two.requests, 2);
  check("one new hold beyond the seeded one", two.holds, 2);

  // A wider race on what is left: 4 x 20000 = 80000 against 58450, so at most
  // two can win and the balance must never cross zero.
  const many = await race(id, "four 20000 requests against 58450", [20000, 20000, 20000, 20000]);
  check("at most two committed", many.created <= 2, true);
  check("every call resolved", many.created + many.overdrawn, 4);
  check("balance never went negative", many.after >= 0, true);
  check("balance moved by exactly the committed amount", many.before - many.after, many.created * 20000);

  console.log("\nrun `npm run db:seed` to restore the seeded state.");
  await prisma.$disconnect();
}

main().catch(async (error) => {
  console.error("script failed:", error);
  process.exitCode = 1;
  await prisma.$disconnect();
});

