  const page = await browser.newPage({ viewport: { width: 1000, height: 1100 } });

  const before = await state();
  console.log("baseline:", before, "\n");

  await page.goto(`${BASE}/wallet`);
  await page.screenshot({ path: "shot-1-initial.png", fullPage: true });

  console.log("--- A. invalid amounts are refused with a message and no write ---");
  for (const bad of ["", "abc", "0"]) {
    await page.fill("#amountDollars", bad);
    await page.click("button[type=submit]");
    const alert = await page.getByRole("alert").textContent();
    const after = await state();
    console.log(`  input ${JSON.stringify(bad)} -> "${alert}"`);
    check(`  ${JSON.stringify(bad)} wrote nothing`, after, before);
  }
  await page.screenshot({ path: "shot-2-invalid.png", fullPage: true });

  console.log("\n--- B. overdraft is refused and writes nothing ---");
  await page.fill("#amountDollars", "5000.00");
  await page.click("button[type=submit]");
  await page.getByRole("alert").waitFor();
  console.log(`  "${await page.getByRole("alert").textContent()}"`);
  check("  overdraft wrote nothing", await state(), before);
  await page.screenshot({ path: "shot-3-overdraft.png", fullPage: true });

  console.log("\n--- C. a valid $50.00 request ---");
  await page.fill("#amountDollars", "50.00");
  await page.click("button[type=submit]");
  await page.getByRole("status").waitFor();
  console.log(`  "${await page.getByRole("status").textContent()}"`);
  const afterValid = await state();
  check("  requests +1", afterValid.requests - before.requests, 1);
  check("  holds +1", afterValid.holds - before.holds, 1);
  check("  available dropped exactly 5000 minor", before.available - afterValid.available, 5000);

  // The card must show the new figure with no manual reload: revalidatePath re-rendered it.
  const cardText = await page.getByRole("heading", { name: "Available balance" }).locator("..").textContent();
  console.log(`  available card now reads: ${cardText?.match(/\$[\d,]+\.\d\d/)?.[0]}`);
  check("  card shows 1,234.50 without a reload", cardText?.includes("$1,234.50"), true);

  const pendingRows = page.getByRole("table").locator("tbody tr").filter({ hasText: "Pending" });
  check("  one Pending row in history", await pendingRows.count(), 1);
  await page.screenshot({ path: "shot-4-success.png", fullPage: true });

  console.log("\n--- D. keyboard only: tab to the field, type, submit with Enter ---");
  await page.reload();
  await page.keyboard.press("Tab");
  let focused = await page.evaluate(() => document.activeElement?.id || document.activeElement?.tagName);
  let guard = 0;
  while (focused !== "amountDollars" && guard++ < 12) {
    await page.keyboard.press("Tab");
    focused = await page.evaluate(() => document.activeElement?.id || document.activeElement?.tagName);
  }
  check("  amount input is reachable by Tab", focused, "amountDollars");
  const ring = await page.locator("#amountDollars").evaluate((el) => getComputedStyle(el).outlineWidth);
  console.log(`  focus outline width: ${ring}`);
  await page.screenshot({ path: "shot-5-focus.png", fullPage: true });

  const beforeKeyboard = await state();
  await page.keyboard.type("10");
  await page.keyboard.press("Enter");
  await page.getByRole("status").waitFor();
  console.log(`  "${await page.getByRole("status").textContent()}"`);
  const afterKeyboard = await state();
  check("  keyboard submit created one request", afterKeyboard.requests - beforeKeyboard.requests, 1);
  check("  keyboard submit took exactly 1000 minor", beforeKeyboard.available - afterKeyboard.available, 1000);

  console.log("\n--- E. double submit without reloading yields ONE request ---");
  const beforeDouble = await state();
  await page.fill("#amountDollars", "12.34");
  // Two submits of the same rendered form, so the same minted key goes twice.
  await Promise.all([
    page.click("button[type=submit]"),
    page.click("button[type=submit]", { force: true }).catch(() => {}),
  ]);
  await page.waitForTimeout(2500);
  await page.evaluate(() => new Promise((r) => setTimeout(r, 500)));
  const afterDouble = await state();
  console.log(`  status: "${await page.getByRole("status").textContent().catch(() => "none")}"`);
  check("  exactly one new request", afterDouble.requests - beforeDouble.requests, 1);
  check("  exactly one new hold", afterDouble.holds - beforeDouble.holds, 1);
  check("  balance moved by 1234 once", beforeDouble.available - afterDouble.available, 1234);
  await page.screenshot({ path: "shot-6-double.png", fullPage: true });

  await browser.close();
  await prisma.$disconnect();
}

main().catch(async (e) => {
  console.error("failed:", e);
  process.exitCode = 1;
  await prisma.$disconnect();
});
EOF
