import { chromium } from "@playwright/test";
import { LedgerEntryType } from "@/lib/generated/prisma/enums";
import { prisma } from "@/lib/prisma";
import { sumAvailableBalance } from "@/lib/wallet";

const BASE = "http://localhost:3100";

async function state() {
  const c = await prisma.creator.findFirstOrThrow();
  const [available, requests, holds] = await Promise.all([
    sumAvailableBalance(prisma, c.id),
    prisma.payoutRequest.count({ where: { creatorId: c.id } }),
    prisma.ledgerEntry.count({ where: { creatorId: c.id, type: LedgerEntryType.PAYOUT_HOLD } }),
  ]);
  return { available, requests, holds };
}

function check(label: string, actual: unknown, expected: unknown) {
  const pass = JSON.stringify(actual) === JSON.stringify(expected);
  console.log(`${pass ? "PASS" : "FAIL"}  ${label} (expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)})`);
  if (!pass) process.exitCode = 1;
}

async function main() {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1000, height: 1000 } });
  page.setDefaultTimeout(45_000);

  await page.goto(`${BASE}/wallet`);
  await page.getByRole("heading", { name: "Wallet", level: 1 }).waitFor();

  console.log("--- is the submit button disabled while pending? ---");
  console.log("   disabled attr present in idle DOM:", await page.locator("button[type=submit]").isDisabled());

  const before = await state();
  const key = await page.locator("input[name=idempotencyKey]").inputValue();
  console.log(`   minted key on this render: ${key.slice(0, 14)}...`);

  console.log("\n--- two submits of the SAME rendered form, in one tick ---");
  await page.fill("#amountDollars", "7.77");
  // requestSubmit twice synchronously: React has not flipped isPending yet, so
  // the disabled button cannot intervene and both carry the same minted key.
  const fired = await page.evaluate(() => {
    const form = document.querySelector("form") as HTMLFormElement;
    form.requestSubmit();
    form.requestSubmit();
    return true;
  });
  console.log("   fired twice:", fired);

  await page.waitForTimeout(12_000);
  const after = await state();
  console.log(`   balance ${before.available} -> ${after.available}`);
  check("   exactly one new request", after.requests - before.requests, 1);
  check("   exactly one new hold", after.holds - before.holds, 1);
  check("   balance moved by 777 once", before.available - after.available, 777);

