  await page.screenshot({ path: "shot-6-double.png", fullPage: true });

  console.log("\n--- does the key rotate on the next render? ---");
  await page.reload();
  const key2 = await page.locator("input[name=idempotencyKey]").inputValue();
  check("   a fresh render mints a different key", key2 !== key, true);
  console.log(`   ${key.slice(0, 14)}... -> ${key2.slice(0, 14)}...`);

  await browser.close();
  await prisma.$disconnect();
}

main().catch(async (e) => {
  console.error("failed:", e);
  process.exitCode = 1;
  await prisma.$disconnect();
  process.exit(1);
});
